import math

def is_power_of_two(n):
    """Checks if n is a power of two."""
    if n <= 0:
        return False
    return (n & (n - 1) == 0)

solutions = []
Ns = [4, 5, 6]
X_max = 30

print("Starting computational search for n=4, 5, 6 and x up to 30.")

for n in Ns:
    start_x = n + 1
    print(f"\n--- Checking n = {n} ---")

    # Pruning based on W7 bounds for rough estimation (optional, but good practice)
    # k_lower_bound = n * math.log2(start_x)
    # k_upper_bound = n * math.log2(start_x) + 1

    for x in range(start_x, X_max + 1):
        # Calculate V = x^n + x - 2
        try:
            V = x**n + x - 2
        except OverflowError:
            # Skip if V is too large to handle standard integer types
            # Given X_max=30, n=6, 30^6 is about 729 million, which is safe.
            continue 

        if is_power_of_two(V):
            k = int(math.log2(V))
            solutions.append((x, n, k))
            print(f"Found solution for n={n}, x={x}: V = {V} = 2^{k} (k={k})")

print("\n--- Search Complete ---")
if solutions:
    print("\nAll found solutions (x, n, k):")
    for sol in solutions:
        print(sol)
else:
    print("\nNo solutions found in the specified range.")

